#!/usr/bin/env bash
# 安装 git pre-commit hook：迁移回归 + 契约一致性 + 容灾测试
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HOOK="$ROOT/.git/hooks/pre-commit"

if [ ! -d "$ROOT/.git" ]; then
  echo "❌ 非 git 仓库：$ROOT"
  exit 0
fi

cat > "$HOOK" << 'HOOK_EOF'
#!/usr/bin/env bash
# auto-generated by scripts/pre_commit_install.sh
set -e
ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"

echo "▶ pre-commit: 迁移回归门"
PYTHONDONTWRITEBYTECODE=1 python3 backend/tests/migration_regression.py || exit 1

echo "▶ pre-commit: 契约一致性"
PYTHONDONTWRITEBYTECODE=1 python3 -c "
import re, sys
sys.path.insert(0, '.')
from backend.core.model_registry.api_routes import routes
from backend.core.model_registry.contract import ENDPOINTS
norm = lambda p: re.sub(r'\{[^}]+\}', '{X}', p)
impl = {(m, norm(p)) for m, p, _ in routes()}
decl = {(v['method'], norm(v['path'])) for v in ENDPOINTS.values()}
diff = impl ^ decl
if diff:
    print('契约与实现不一致:', diff); sys.exit(1)
print('✅ 契约一致')
" || exit 1

echo "▶ pre-commit: 容灾测试"
PYTHONDONTWRITEBYTECODE=1 python3 backend/tests/model_registry/test_failover.py > /dev/null || exit 1

echo "✅ pre-commit 全部通过"
HOOK_EOF
chmod +x "$HOOK"
echo "✅ hook 已安装: $HOOK"
